@testset "Primal bound cleanup honors cancellation and auxiliary isolation" begin
    ws,policy=shifted_primal_workspace()
    auxiliary=JSimplex._auxiliary_workspace(ws)
    @test !auxiliary.scratch.primal_perturbation_allowed
    @test isnothing(auxiliary.scratch.perturbations)
    @test !auxiliary.perturbed
    budget=JSimplex.SimplexRunBudget(ws)
    stop=()->JSimplex.event_count(ws.progress.diagnostics,:phase_cleanup)>0
    run=JSimplex.run_from_basis!(ws,budget,policy,stop)
    @test run.status==TIME_LIMIT
    @test JSimplex._original_bounds_active(ws)
    @test !ws.perturbed && isnothing(ws.scratch.perturbations)
    @test ws.iterations==budget.iterations
end

@testset "Primal perturbation shares the completed-step budget and exact branch" begin
    ws,policy=primal_perturbation_chain(iteration_limit=2)
    budget=JSimplex.SimplexRunBudget(ws)
    run=JSimplex.run_from_basis!(ws,budget,policy,()->false)
    @test run.status==ITERATION_LIMIT
    @test ws.iterations==budget.iterations==2
    @test JSimplex.event_count(ws.progress.diagnostics,:perturbation)==1
    @test JSimplex.event_count(ws.progress.diagnostics,:phase_cleanup)==0
    @test ws.scratch.perturbations.bounds.active
    ws,policy=primal_perturbation_chain(Rational{BigInt})
    run=JSimplex.run_from_basis!(ws,JSimplex.SimplexRunBudget(ws),policy,()->false)
    @test run.status==OPTIMAL && run.primal==[1,1,1]
    @test JSimplex.event_count(ws.progress.diagnostics,:perturbation)==0
    @test isnothing(ws.scratch.perturbations)
end

@testset "Driver honors zero remaining iterations and an expired clock" begin
    p = LinearProblem(sparse([1.0;;]),[-1.0];row_upper=[2.0])
    w = _checked_simplex_driver_workspace(p,SolverOptions(verbose=false,simplex_strategy=:adaptive,iteration_limit=0))
    b = JSimplex.SimplexRunBudget(w)
    @test JSimplex.run_from_basis!(w,b,w.progress.numerical_policy,()->false).status == ITERATION_LIMIT
    @test w.iterations == b.iterations == 0
    w = _checked_simplex_driver_workspace(p,SolverOptions(verbose=false,simplex_strategy=:adaptive,time_limit=0.0))
    b = JSimplex.SimplexRunBudget(w)
    @test JSimplex.run_from_basis!(w,b,w.progress.numerical_policy,()->false).status == TIME_LIMIT
    @test w.iterations == 0
end

@testset "Auxiliary phases respect cancellation and preserve user errors" begin
    for throwing in (false,true)
        entered = Ref(false)
        d = JSimplex.SimplexDiagnostics(;observer=(event,ws)->begin
            event == :phase_auxiliary && (entered[] = true)
        end)
        p = LinearProblem(sparse([1.0;;]),[-1.0];row_lower=[1.0],row_upper=[2.0])
        o = SolverOptions(verbose=false,simplex_strategy=:adaptive)
        w = _checked_simplex_driver_workspace(p,o;progress=JSimplex.SimplexProgressContext(p;
            diagnostics=d,numerical_policy=JSimplex.NumericalPolicy(Float64; numerical_profile=:checked, simplex_strategy=o.simplex_strategy)))
        b = JSimplex.SimplexRunBudget(w)
        failure = JSimplex.ZeroPivotException(9)
        stop = () -> entered[] ? (throwing ? throw(failure) : true) : false
        result = try
            JSimplex.run_from_basis!(w,b,w.progress.numerical_policy,stop)
        catch e
            e
        end
        @test entered[]
        @test throwing ? result === failure : result.status == TIME_LIMIT
        @test b.iterations == w.iterations == 0
        @test b.refactorizations == w.refactorizations
    end
end

@testset "A shared budget cannot be replenished by a fresh workspace" begin
    p = LinearProblem(sparse([1.0;;]),[-1.0];row_upper=[2.0])
    o = SolverOptions(verbose=false,simplex_strategy=:adaptive,iteration_limit=2)
    w = _checked_simplex_driver_workspace(p,o)
    budget = JSimplex.SimplexRunBudget(w)
    @test JSimplex.run_from_basis!(w,budget,w.progress.numerical_policy,()->false).status == OPTIMAL
    @test budget.iterations == 1
    q = LinearProblem(sparse([1.0 0.0;0.0 1.0]),[-1.0,-1.0];row_upper=[2.0,2.0])
    fresh = _checked_simplex_driver_workspace(q,o)
    result = JSimplex.run_from_basis!(fresh,budget,fresh.progress.numerical_policy,()->false)
    @test result.status == ITERATION_LIMIT
    @test result.iterations == budget.iterations == 2
end

@testset "Replacement workspaces pass the shared deadline to inner solves" begin
    for algorithm in (:primal,:dual)
        p = algorithm == :primal ? LinearProblem(sparse([1.0;;]),[-1.0];row_upper=[2.0]) :
            LinearProblem(sparse([1.0;;]),[1.0];row_lower=[1.0])
        o = SolverOptions(;algorithm,verbose=false,simplex_strategy=:adaptive)
        original = _checked_simplex_driver_workspace(p,o)
        budget = JSimplex.SimplexRunBudget(original)
        budget.time_limit_seconds = 120.0
        clocks = Tuple{UInt64,Float64}[]
        diagnostics = JSimplex.SimplexDiagnostics(;observer=(event,ws)->begin
            if event in (:phase_primal,:phase_dual)
                clock = JSimplex._basis_solve_stop(ws,nothing)
                push!(clocks,(clock.start_ns,clock.limit_seconds))
            end
        end)
        fresh = _checked_simplex_driver_workspace(p,o;progress=JSimplex.SimplexProgressContext(p;
            diagnostics,numerical_policy=JSimplex.NumericalPolicy(Float64; numerical_profile=:checked, simplex_strategy=o.simplex_strategy)))
        result = JSimplex.run_from_basis!(fresh,budget,fresh.progress.numerical_policy,()->false)
        @test result.status == OPTIMAL
        @test !isempty(clocks)
        @test all(clock->clock[1]==budget.start_ns,clocks)
        @test all(clock->clock[2]==budget.time_limit_seconds,clocks)
        @test fresh.options === o
    end
end

@testset "Native cleanup retires an owned bound journal after heuristics are disabled" begin
    ws, _ = shifted_primal_workspace()
    @test JSimplex._primal_optimize!(ws, ()->false).status == OPTIMAL
    policy = JSimplex.NumericalPolicy(Float64)
    JSimplex._install_driver_policy!(ws, policy)
    @test JSimplex._original_objective_driver_required(ws)
    run = JSimplex.run_from_basis!(ws, JSimplex.SimplexRunBudget(ws), policy, ()->false)
    @test run.status == OPTIMAL && run.primal == [0.0]
    @test JSimplex._original_bounds_active(ws)
    @test isnothing(ws.scratch.perturbations)
    @test !ws.progress.numerical_policy.feasibility_recovery
end

@testset "Basis recovery preserves active bound ownership and cooldown" begin
    ws,policy=primal_perturbation_workspace()
    journal=JSimplex.PerturbationJournal(ws)
    @test JSimplex.perturb_primal_bounds!(ws,primal_stalled_monitor(Float64,policy),journal,policy)==2
    lower,upper=copy(ws.lower),copy(ws.upper)
    checkpoint=JSimplex.checkpoint_basis(ws)
    @test JSimplex.restore_checkpoint!(ws,checkpoint,()->false)
    @test ws.scratch.perturbations===journal && journal.bounds.active
    @test ws.lower===journal.bounds.active_lower && ws.upper===journal.bounds.active_upper
    @test isequal((ws.lower,ws.upper),(lower,upper))
    @test journal.bounds.cooldown_until>=ws.iterations+2policy.stagnation_window
    @test journal.bounds.level==1 && journal.level==0
end

@testset "Original-cost cleanup shares the completed-step and time budgets" begin
    ws,policy = perturbation_chain_workspace(iteration_limit=2)
    budget = JSimplex.SimplexRunBudget(ws)
    result = JSimplex.run_from_basis!(ws,budget,policy,()->false)
    @test result.status == ITERATION_LIMIT
    @test ws.iterations == budget.iterations == 2
    @test JSimplex.event_count(ws.progress.diagnostics,:perturbation) == 1
    @test JSimplex.event_count(ws.progress.diagnostics,:phase_cleanup) == 0
    ws,policy = perturbation_chain_workspace()
    budget = JSimplex.SimplexRunBudget(ws)
    # Cancellation immediately after restoration cannot certify a stale price.
    stop = () -> JSimplex.event_count(ws.progress.diagnostics,:phase_cleanup) > 0
    result = JSimplex.run_from_basis!(ws,budget,policy,stop)
    @test result.status == TIME_LIMIT
    @test ws.iterations == budget.iterations == 3
    @test !ws.perturbed && isnothing(ws.scratch.perturbations)
    @test all(iszero,ws.costs)
end
